        private void BindTaskFileUi(string link)
        {
            string normalized = NormalizeTaskLink(link);
            if (hidTaskLink != null)
                hidTaskLink.Value = normalized ?? string.Empty;
            if (hidClearTaskFile != null && !string.IsNullOrWhiteSpace(normalized))
                hidClearTaskFile.Value = "0";

            if (txtTaskLink != null)
            {
                if (string.IsNullOrWhiteSpace(normalized))
                    txtTaskLink.Text = string.Empty;
                else
                    txtTaskLink.Text = Path.GetFileName(normalized.Replace('/', '\\'));
            }

            bool hasFile = !string.IsNullOrWhiteSpace(normalized);
            SessionUser objUser = Session[Globals.USER] as SessionUser;
            string userName = objUser != null ? objUser.UserName : string.Empty;

            if (hlTaskFile != null)
            {
                if (hasFile)
                {
                    string url = BuildTaskFileDownloadUrl(normalized, userName);
                    hlTaskFile.NavigateUrl = url;
                    hlTaskFile.Visible = !string.IsNullOrWhiteSpace(url);
                }
                else
                {
                    hlTaskFile.NavigateUrl = string.Empty;
                    hlTaskFile.Visible = false;
                }
            }

            if (lbtRemoveTaskFile != null)
                lbtRemoveTaskFile.Visible = hasFile && EmployeeV2TabCanEdit.CanEdit(Session);
        }

        private string GetStoredTaskLink()
        {
            if (hidTaskLink == null)
                return string.Empty;
            return hidTaskLink.Value ?? string.Empty;
        }

        private bool IsClearTaskFileRequested()
        {
            if (hidClearTaskFile == null)
                return false;
            return string.Equals(hidClearTaskFile.Value, "1", StringComparison.Ordinal);
        }

        private static string NormalizeTaskLink(string link)
        {
            if (string.IsNullOrWhiteSpace(link))
                return null;
            return link.Trim().Replace('\\', '/');
        }

        private static bool IsAllowedTaskFileName(string fileName)
        {
            if (string.IsNullOrWhiteSpace(fileName))
                return false;

            string ext = Path.GetExtension(fileName).ToLowerInvariant();
            for (int i = 0; i < TaskFileAllowedExtensions.Length; i++)
            {
                if (TaskFileAllowedExtensions[i] == ext)
                    return true;
            }
            return false;
        }

        private static string BuildTaskLinkRelativePath(long employeeId, long taskId, string extension)
        {
            return string.Format(CultureInfo.InvariantCulture, "{0}/{1}/{2}{3}",
                TaskFileFolderPrefix, employeeId, taskId, extension);
        }

        private static string GetUploadRootPhysicalPath(HttpServerUtility server)
        {
            string basePath = DCore.Globals.GetConfig("PhysicalDirectory_Upload");
            if (string.IsNullOrWhiteSpace(basePath))
            {
                if (server != null)
                    basePath = server.MapPath("~/Media");
                else
                    basePath = string.Empty;
            }
            return basePath != null ? basePath.TrimEnd('\\', '/') : string.Empty;
        }

        private static string GetTaskFilePhysicalPath(string link)
        {
            if (string.IsNullOrWhiteSpace(link))
                return string.Empty;

            string root = GetUploadRootPhysicalPath(HttpContext.Current != null ? HttpContext.Current.Server : null);
            if (string.IsNullOrWhiteSpace(root))
                return string.Empty;

            string relative = link.Trim().Replace('/', '\\').TrimStart('\\');
            return Path.Combine(root, relative);
        }

        private string SaveTaskFileToDisk(long taskId, long employeeId, FileUpload upload)
        {
            if (taskId <= 0 || employeeId <= 0 || upload == null || !upload.HasFile)
                return null;

            if (!IsAllowedTaskFileName(upload.FileName))
                return null;

            string ext = Path.GetExtension(upload.FileName).ToLowerInvariant();
            string link = BuildTaskLinkRelativePath(employeeId, taskId, ext);
            string fullPath = GetTaskFilePhysicalPath(link);
            if (string.IsNullOrWhiteSpace(fullPath))
                return null;

            string dir = Path.GetDirectoryName(fullPath);
            if (!string.IsNullOrWhiteSpace(dir) && !Directory.Exists(dir))
            {
                try
                {
                    Directory.CreateDirectory(dir);
                }
                catch (Exception ex)
                {
                    System.Diagnostics.Debug.WriteLine("TabCongTacEdit.SaveTaskFileToDisk: " + ex.Message);
                    return null;
                }
            }

            try
            {
                upload.SaveAs(fullPath);
                return link;
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine("TabCongTacEdit.SaveTaskFileToDisk: " + ex.Message);
                return null;
            }
        }

        private static void DeleteTaskFilePhysical(string link)
        {
            string path = GetTaskFilePhysicalPath(link);
            if (string.IsNullOrWhiteSpace(path) || !File.Exists(path))
                return;

            try
            {
                File.Delete(path);
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine("TabCongTacEdit.DeleteTaskFilePhysical: " + ex.Message);
            }
        }

